import numpy as np

def get_humidity_band(h):
    if h < 60:
        return '<60%'
    elif h <= 75:
        return '60-75%'
    else:
        return '≥75%'

df['습도구간'] = df['외기습도 (%)'].apply(get_humidity_band)
